1	/* Segue DESIGN.md: cores calmas, contraste AA, alvos grandes, movimento curto. */
2	@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
3	@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }
4	
5	:root {
6	  /* Marca Gump: verde esmeralda + rosa rubi + pêssego sobre creme rosado. */
7	  --verde: #2E9E6B;
8	  --verde-forte: #1F7A50;
9	  --verde-claro: #EEF8F2;
10	  --rubi: #D9406E;
11	  --rubi-forte: #B8325A;
12	  --rubi-claro: #FBE1E9;
13	  --pessego: #FF9F6B;
14	  --pessego-claro: #FFE6D6;
15	  --papel: #FFF6F0;
16	  --cartao: #ffffff;
17	  --tinta: #1E3B2F;
18	  --suave: #55665D;
19	  --ok: var(--verde-forte);
20	  --alerta: #9A4A12;
21	  --erro: #A8324F;
22	  --borda: #EADBD0;
23	  --sombra: 0 1px 2px rgba(30, 59, 47, 0.06), 0 6px 20px rgba(30, 59, 47, 0.07);
24	  --titulo: 'Fredoka', 'Atkinson', sans-serif;
25	  /* Tokens do tema de hiperfoco (trocados por estiloTema()). */
26	  --tema: var(--verde);
27	  --tema-fundo: var(--verde-claro);
28	  --ceu: #DDEEE5;
29	  --chao: #BFDACA;
30	  --chao-longe: #D0E4D7;
31	  font-family: 'Atkinson', system-ui, sans-serif;
32	  color: var(--tinta);
33	  background: var(--papel);
34	  line-height: 1.5;
35	}
36	
37	* { box-sizing: border-box; }
38	body { margin: 0; background: var(--papel); }
39	h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 8px; }
40	h1 { font-size: 1.6rem; }
41	h2 { font-size: 1.2rem; }
42	a { color: var(--ok); }
43	img { max-width: 100%; }
44	.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
45	
46	button, .botao {
47	  font: inherit; font-weight: 700; color: var(--tinta);
48	  min-height: 48px; min-width: 48px; padding: 0 16px; gap: 8px;
49	  border: 2px solid var(--tinta); border-radius: 12px; background: var(--cartao);
50	  cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; justify-content: center;
51	  transition: transform 120ms ease, background-color 150ms ease, box-shadow 150ms ease;
52	}
53	button:active { transform: scale(0.97); }
54	button:disabled { opacity: 0.45; cursor: default; }
55	button.primario { background: var(--verde-forte); border-color: var(--verde-forte); color: #fff; }
56	button.primario:hover:not(:disabled) { background: var(--tinta); border-color: var(--tinta); }
57	button:focus-visible, .botao:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--ok); outline-offset: 3px; }
58	
59	input, select { font: inherit; min-height: 48px; padding: 0 14px; border: 2px solid var(--borda); border-radius: 12px; background: var(--cartao); color: var(--tinta); }
60	input:hover, select:hover { border-color: #D9C4B5; }
61	input[type='file'] { padding: 10px; }
62	label { display: flex; flex-direction: column; gap: 6px; font-weight: 700; }
63	
64	.ajuda { color: var(--suave); margin: 4px 0; }
65	.erro { color: var(--erro); font-weight: 700; }
66	.linha { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; }
67	.linha.centro { justify-content: center; }
68	.cartao { background: var(--cartao); border: 1px solid var(--borda); border-radius: 16px; padding: 20px; }
