131	.aluno-topo h1 { font-family: var(--titulo); font-size: 2.2rem; margin: 0; }
132	.aluno-topo .ajuda { margin: 0; }
133	.aluno-avatar { flex: none; width: 76px; height: 76px; border-radius: 50%; overflow: hidden; display: grid; place-items: center; background: var(--pessego); color: var(--tinta); font-family: var(--titulo); font-weight: 700; font-size: 2rem; border: 3px solid var(--cartao); box-shadow: 0 0 0 3px var(--pessego); }
134	.aluno-avatar img { width: 82%; height: 82%; }
135	.fichas { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
136	.fichas li { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; background: var(--cartao); border: 1px solid var(--borda); color: var(--suave); }
137	.fichas svg { color: var(--rubi-forte); }
138	.fichas strong { color: var(--tinta); font-size: 1.1rem; }
139	
140	.passos { list-style: none; margin: 0; padding: 16px 20px; display: flex; gap: 8px; background: var(--cartao); border-radius: 18px; border: 1px solid var(--borda); }
141	.passos li { flex: 1; display: flex; align-items: center; gap: 10px; font-weight: 700; color: var(--suave); }
142	.passos li:not(:last-child)::after { content: ''; flex: 1; height: 3px; border-radius: 3px; background: var(--borda); margin-left: 4px; }
143	.passos li.feito:not(:last-child)::after { background: var(--verde); }
144	.passo-marca { flex: none; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: #F3E9E1; color: var(--suave); }
145	.passos li.atual { color: var(--tinta); }
146	.passos li.atual .passo-marca { background: var(--pessego); color: var(--tinta); }
147	.passos li.feito { color: var(--verde-forte); }
148	.passos li.feito .passo-marca { background: var(--verde-forte); color: #fff; }
149	
150	.bloco { background: var(--cartao); border: 1px solid var(--borda); border-radius: 20px; padding: 24px; display: flex; flex-direction: column; gap: 14px; box-shadow: var(--sombra); }
151	.bloco h2 { font-family: var(--titulo); font-size: 1.45rem; font-weight: 600; margin: 0; }
152	.bloco > p { margin: 0; }
153	.bloco-titulo { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
154	.nota-ia { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; font-size: 0.95rem; }
155	.vazio { margin: 0; padding: 20px; border-radius: 14px; background: var(--papel); color: var(--suave); text-align: center; }
156	.aviso-acao { margin: 0; padding: 12px 16px; border-radius: 12px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; display: flex; align-items: center; gap: 8px; }
157	.aviso-calmo { margin: 0; padding: 14px 16px; border-radius: 14px; background: var(--verde-claro); display: flex; gap: 12px; align-items: flex-start; }
158	.aviso-calmo svg { flex: none; color: var(--verde-forte); margin-top: 2px; }
159	
160	.envio { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
161	.soltar { width: 100%; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center; padding: 28px 16px; border: 2px dashed var(--verde); border-radius: 16px; background: var(--verde-claro); font-weight: 400; }
162	.soltar:hover, .soltar:focus-within { background: #E2F3E9; }
163	.soltar:focus-within { outline: 3px solid var(--verde-forte); outline-offset: 3px; }
164	.soltar strong { font-size: 1.1rem; }
165	.soltar input { position: absolute; width: 1px; height: 1px; opacity: 0; }
166	.soltar-icone { width: 60px; height: 60px; border-radius: 50%; display: grid; place-items: center; background: var(--cartao); color: var(--verde-forte); }
167	.soltar.com-arquivo { border-style: solid; }
168	
169	.grade-topicos { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
170	.topico { padding: 18px; border-radius: 16px; display: flex; flex-direction: column; gap: 8px; }
171	.topico p { margin: 0; color: var(--tinta); font-size: 0.95rem; }
172	.topico-icone { flex: none; width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center; background: var(--cartao); }
173	.cor-verde { background: var(--verde-claro); } .cor-verde .topico-icone, .sugestao-capa.cor-verde, .lista-jogos-icone.cor-verde { color: var(--verde-forte); }
174	.cor-rubi { background: var(--rubi-claro); } .cor-rubi .topico-icone, .sugestao-capa.cor-rubi, .lista-jogos-icone.cor-rubi { color: var(--rubi-forte); }
175	.cor-pessego { background: var(--pessego-claro); } .cor-pessego .topico-icone, .sugestao-capa.cor-pessego, .lista-jogos-icone.cor-pessego { color: var(--alerta); }
176	
177	/* Resumo para a família: um cartão por tópico. */
178	.grade-topicos-pais { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; }
179	.topico-pais { padding: 20px; border-radius: 18px; display: flex; flex-direction: column; gap: 14px; }
180	.topico-pais-titulo { display: flex; align-items: center; gap: 12px; }
181	.topico-pais h3 { font-family: var(--titulo); font-weight: 600; font-size: 1.25rem; margin: 0; }
182	.topico-parte { background: rgba(255, 255, 255, 0.75); border-radius: 12px; padding: 12px 14px; }
183	.topico-parte h4 { display: flex; align-items: center; gap: 6px; font-size: 0.95rem; margin: 0 0 6px; color: var(--suave); }
184	.topico-parte p { margin: 0; }
185	.topico-parte ul { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 4px; }
186	.topico-parte .links { list-style: none; padding: 0; }
187	.links a { font-weight: 700; }
188	
189	.grade-cartoes-jogo { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }
190	.cartao-sugestao { border: 2px solid var(--borda); border-radius: 18px; overflow: hidden; display: flex; flex-direction: column; background: var(--cartao); }
191	.sugestao-capa { position: relative; height: 110px; display: grid; place-items: center; }
192	.sugestao-capa .selo { position: absolute; top: 10px; right: 10px; background: var(--cartao); }
193	.sugestao-corpo { padding: 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
194	.sugestao-corpo strong { font-size: 1.15rem; }
195	.sugestao-corpo .ajuda { margin: 0; }
196	.sugestao-corpo .linha { margin-top: auto; padding-top: 8px; }
197	.sugestao-corpo button { flex: 1; }
198	.cartao-sugestao.status-sugerido { border-color: var(--pessego); }
199	.cartao-sugestao.status-aprovado { border-color: var(--verde); }
200	.cartao-sugestao.status-recusado { opacity: 0.6; }
201	
202	.lista-jogos { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; }
203	.lista-jogos li { display: flex; gap: 14px; align-items: center; padding: 14px; border: 1px solid var(--borda); border-radius: 16px; }
204	.lista-jogos .ajuda { margin: 0; }
205	.lista-jogos-icone { flex: none; width: 56px; height: 56px; border-radius: 16px; display: grid; place-items: center; }
206	
207	.etiquetas { list-style: none; padding: 0; margin: 8px 0; display: flex; flex-wrap: wrap; gap: 8px; }
208	.etiquetas li { padding: 6px 12px; border-radius: 999px; background: var(--verde-claro); color: var(--ok); font-weight: 700; }
209	.etiquetas li:not(.do-pdi) { background: transparent; color: var(--tinta); border: 1px dashed currentColor; font-weight: 400; }
210	.etiquetas li.do-pdi { display: inline-flex; align-items: center; gap: 4px; }
211	
212	.selo { font-size: 0.9rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; background: #F3E9E1; }
213	.status-sugerido .selo { background: var(--pessego-claro); color: var(--alerta); }
214	.status-aprovado .selo { background: var(--verde-claro); color: var(--ok); }
215	
216	/* Desempenho: números de resumo + barras horizontais. */
217	.painel { display: flex; flex-direction: column; gap: 18px; }
218	.painel h3 { font-size: 1.05rem; margin: 0; }
219	.numeros { margin: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
220	.numero { padding: 14px 16px; border-radius: 14px; background: var(--papel); border: 1px solid var(--borda); }
221	.numero dt { color: var(--suave); font-weight: 700; font-size: 0.95rem; }
222	.numero dd { margin: 2px 0 0; font-family: var(--titulo); font-weight: 600; font-size: 2rem; line-height: 1.1; }
223	.barras { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 14px; }
224	.barras-topo { display: flex; justify-content: space-between; gap: 12px; }
225	.barras-topo span { font-weight: 700; color: var(--verde-forte); }
226	.barras .ajuda { margin: 4px 0 0; font-size: 0.95rem; }
227	.barra { height: 14px; margin-top: 6px; border-radius: 999px; background: #F3E9E1; overflow: hidden; }
228	.barra span { display: block; height: 100%; border-radius: 999px; background: var(--verde); }
229	
230	/* ---------------------------------------------------------------- Área da criança */
231	/* Mesma estrutura em todos os temas: só os tokens do tema mudam. */
232	.crianca { min-height: 100dvh; background: var(--tema-fundo); padding-bottom: 56px; font-size: 1.15rem; }
233	.crianca-barra { display: flex; justify-content: space-between; align-items: center; gap: 12px; max-width: 960px; margin: 0 auto; padding: 16px; }
234	.crianca button { min-height: 64px; border-radius: 18px; }
235	.botao-crianca { border: 2px solid color-mix(in srgb, var(--tema) 35%, transparent); background: var(--cartao); padding: 0 20px 0 14px; box-shadow: 0 3px 0 color-mix(in srgb, var(--tema) 25%, transparent); }
236	.botao-crianca:hover { border-color: var(--tema); }
237	.crianca button.primario { background: var(--tema); border-color: var(--tema); color: #fff; box-shadow: 0 4px 0 color-mix(in srgb, var(--tema) 60%, #000); }
238	.crianca button.primario:hover:not(:disabled) { background: color-mix(in srgb, var(--tema) 85%, #000); border-color: transparent; }
239	.crianca-erro { max-width: 960px; margin: 0 auto 12px; padding: 0 16px; }
240	.crianca-secao { max-width: 960px; margin: 0 auto; padding: 16px; }
241	.crianca-titulo { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-family: var(--titulo); font-weight: 600; font-size: 1.9rem; margin: 8px 0 16px; }
242	.titulo-icone { width: 48px; height: 48px; border-radius: 16px; display: grid; place-items: center; background: var(--tema); color: #fff; }
243	.contador { margin-left: auto; padding: 4px 14px; border-radius: 999px; background: var(--cartao); color: var(--tema); font-family: 'Atkinson', sans-serif; font-weight: 700; font-size: 1.05rem; }
244	
245	/* Palco: cenário do tema com o personagem, o XP e o próximo item. */
246	.palco { position: relative; overflow: hidden; background: var(--ceu); }
247	.cenario { position: absolute; inset: 0; width: 100%; height: 100%; }
248	.c-ceu { fill: var(--ceu); }
249	.c-sol { fill: #fff; opacity: 0.55; }
250	.c-nuvem { fill: #fff; opacity: 0.75; }
251	.c-chao-longe { fill: var(--chao-longe); }
252	.c-chao { fill: var(--chao); }
253	.c-onda { fill: var(--tema-fundo); }
254	.c-detalhe { fill: color-mix(in srgb, var(--tema) 22%, var(--chao)); stroke: color-mix(in srgb, var(--tema) 22%, var(--chao)); }
255	.c-detalhe .c-lava { stroke: color-mix(in srgb, var(--pessego) 55%, var(--chao)); }
256	.c-detalhe-claro { stroke: #fff; opacity: 0.8; }
257	.palco-conteudo { position: relative; max-width: 960px; margin: 0 auto; padding: 24px 16px 64px; display: flex; align-items: flex-end; gap: 12px; }
258	.palco-personagem { flex: none; width: 190px; height: 190px; filter: drop-shadow(0 6px 0 rgba(30, 59, 47, 0.12)); }
259	.palco-balao { position: relative; flex: 1; max-width: 520px; margin-bottom: 28px; padding: 20px 24px; background: var(--cartao); border-radius: 24px; box-shadow: var(--sombra); }
260	.palco-balao::before { content: ''; position: absolute; left: -12px; bottom: 34px; width: 24px; height: 24px; background: var(--cartao); transform: rotate(45deg); border-radius: 4px; }
261	.palco-balao h1 { position: relative; font-family: var(--titulo); font-weight: 600; font-size: 2.3rem; margin: 0 0 10px; }
262	.xp-linha { display: flex; align-items: center; gap: 10px; }
263	.xp-estrela { flex: none; color: var(--pessego); }
264	.xp-estrela svg { fill: var(--pessego); stroke: var(--alerta); }
265	.xp { flex: 1; height: 26px; border-radius: 999px; background: var(--tema-fundo); border: 2px solid color-mix(in srgb, var(--tema) 25%, transparent); overflow: hidden; }
266	.xp span { display: block; height: 100%; border-radius: 999px; background: var(--tema); transition: width 300ms ease; }
267	.xp-proximo { flex: none; width: 52px; height: 52px; padding: 4px; border-radius: 14px; background: var(--tema-fundo); border: 2px dashed var(--tema); }
268	.xp-texto { margin: 8px 0 0; color: var(--suave); }
269	.xp-texto strong { color: var(--tinta); }
270	
271	/* Escolha do tema */
272	.grade-temas { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 18px; margin-bottom: 20px; }
273	.crianca .cartao-tema { flex-direction: column; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--cartao); border-radius: 24px; background: var(--cartao); box-shadow: var(--sombra); }
274	.cartao-tema:hover { border-color: var(--tema); transform: translateY(-3px); }
275	.cartao-tema-arte { width: 100%; display: grid; place-items: center; padding: 18px; background: var(--ceu); }
276	.cartao-tema-arte img { width: 130px; height: 130px; }
277	.cartao-tema-nome { padding: 14px; font-family: var(--titulo); font-weight: 600; font-size: 1.4rem; color: var(--tema); }
278	
279	/* Cartões de jogo: capa grande com arte do tema e botão de jogar. */
280	.grade-jogos { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 20px; }
281	.crianca .cartao-jogo { flex-direction: column; align-items: stretch; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--cartao); border-radius: 26px; background: var(--cartao); box-shadow: var(--sombra); text-align: left; }
282	.cartao-jogo:hover { border-color: var(--tema); transform: translateY(-3px); }
283	.cartao-jogo:hover .cartao-jogo-play { background: color-mix(in srgb, var(--tema) 85%, #000); }
284	.cartao-jogo-capa { position: relative; display: grid; place-items: center; height: 170px; background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6) 0 60px, transparent 61px), var(--ceu); }
285	.capa-1 .cartao-jogo-capa { background: radial-gradient(circle at 75% 70%, rgba(255, 255, 255, 0.6) 0 70px, transparent 71px), var(--pessego-claro); }
286	.capa-2 .cartao-jogo-capa { background: radial-gradient(circle at 25% 75%, rgba(255, 255, 255, 0.6) 0 64px, transparent 65px), var(--rubi-claro); }
287	.cartao-jogo-capa img { width: 124px; height: 124px; }
288	.cartao-jogo-tipo { position: absolute; top: 12px; left: 12px; width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; background: var(--cartao); color: var(--tema); }
289	.cartao-jogo-rodape { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 14px 14px 18px; }
290	.cartao-jogo-nome { font-family: var(--titulo); font-weight: 600; font-size: 1.3rem; line-height: 1.2; }
291	.cartao-jogo-play { flex: none; width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center; background: var(--tema); color: #fff; transition: background-color 150ms ease; }
292	.cartao-jogo-play svg { fill: #fff; }
293	.crianca-vazio { display: flex; align-items: center; gap: 16px; margin: 0; padding: 20px; border-radius: 20px; background: var(--cartao); }
294	
295	/* Coleção: estante com o item ganho, o próximo e os bloqueados (silhueta). */
296	.estante { list-style: none; margin: 0; padding: 20px; display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 14px; border-radius: 26px; background: var(--cartao); box-shadow: var(--sombra); }
297	.item-colecao { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 8px; border-radius: 18px; text-align: center; font-size: 0.95rem; font-weight: 700; line-height: 1.2; }
298	.item-colecao img { width: 72px; height: 72px; }
299	.item-colecao.ganho { background: var(--tema-fundo); }
300	.item-colecao.proximo { border: 2px dashed var(--tema); color: var(--tema); }
301	.item-colecao.proximo img { opacity: 0.4; filter: grayscale(1); }
302	.item-colecao.bloqueado { background: #F6F0EA; color: var(--suave); }
303	.item-colecao.bloqueado img { filter: brightness(0); opacity: 0.12; }
304	
305	/* Tela do jogo */
306	.cartao-centro { display: flex; flex-direction: column; align-items: center; gap: 12px; text-align: center; max-width: 640px; margin-top: 24px; padding: 32px 24px; background: var(--cartao); border-radius: 28px; box-shadow: var(--sombra); }
307	.cartao-centro .crianca-titulo { justify-content: center; margin: 0; }
308	.personagem-centro { width: 150px; height: 150px; }
309	.passo-texto { display: flex; align-items: center; gap: 10px; margin: 0 0 8px; }
310	.passo-texto svg { flex: none; color: var(--tema); }
311	button.grande { min-height: 72px; padding: 0 32px; font-size: 1.25rem; }
312	.selo-estrela { width: 104px; height: 104px; border-radius: 50%; display: grid; place-items: center; background: var(--pessego-claro); color: var(--alerta); animation: aparecer 300ms ease-out; }
313	.selo-estrela svg { fill: var(--pessego); }
314	.item-novo { display: flex; align-items: center; gap: 16px; padding: 12px 20px 12px 12px; margin-bottom: 8px; border-radius: 20px; background: var(--tema-fundo); animation: aparecer 300ms ease-out; }
315	.item-novo img { width: 80px; height: 80px; }
316	.item-novo p { margin: 0; }
317	@keyframes aparecer { from { transform: scale(0.85); opacity: 0; } to { transform: scale(1); opacity: 1; } }
318	
319	.fundo-dialogo { position: fixed; inset: 0; background: rgba(31, 42, 46, 0.45); display: grid; place-items: center; padding: 16px; }
320	.dialogo { background: var(--cartao); border-radius: 24px; padding: 28px 24px; max-width: 420px; width: 100%; text-align: center; box-shadow: var(--sombra); }
321	.dialogo p { font-family: var(--titulo); font-weight: 600; font-size: 1.5rem; margin: 8px 0 20px; }
322	
323	@media (prefers-reduced-motion: reduce) {
324	  * { transition: none !important; animation: none !important; }
325	}
326	
327	@media (max-width: 760px) {
328	  .passos { flex-direction: column; align-items: stretch; }
329	  .passos li:not(:last-child)::after { display: none; }
330	  .cabecalho { padding: 10px 16px; }
331	  .cabecalho-meio { order: 3; flex-basis: 100%; justify-content: flex-start; }
332	  .quem { display: none; }
333	  .login { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
334	  .login-marca { padding: 32px 16px; gap: 12px; }
335	  .login-marca .logo { font-size: 48px !important; }
336	  .login-frase { font-size: 1.25rem; }
337	  .login-passos, .login-turma { display: none; }
338	  .palco-conteudo { flex-direction: column; align-items: center; padding-bottom: 48px; }
339	  .palco-personagem { width: 140px; height: 140px; }
340	  .palco-balao { width: 100%; margin-bottom: 0; }
341	  .palco-balao::before { left: calc(50% - 12px); top: -10px; bottom: auto; }
342	  .palco-balao h1 { font-size: 1.9rem; }
343	}
344	
345	@media (max-width: 600px) {
346	  .crianca-titulo { font-size: 1.5rem; }
347	  .estante { grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); padding: 14px; }
348	}
349	
350	/* Logo do Gump */
351	.logo { display: inline-flex; align-items: center; gap: 0.1em; font-family: var(--titulo); font-weight: 700; color: #2E9E6B; letter-spacing: -0.02em; line-height: 1; }
352	.logo img { height: 1.45em; width: auto; }
353	
354	/* Palco onde o jogo do hub é montado. Os jogos usam height:100%, então o palco precisa de altura definida. */
355	.crianca-jogo { display: flex; flex-direction: column; height: 100dvh; box-sizing: border-box; }
356	.crianca-jogo { padding-bottom: 0; }
357	.crianca-jogo .crianca-barra { width: 100%; box-sizing: border-box; }
358	.crianca-barra-titulo { font-family: var(--titulo); font-size: 1.4rem; }
359	.palco-jogo { position: relative; flex: 1; min-height: 0; width: 100%; max-width: 880px; margin: 0 auto; overflow: hidden; border-radius: 16px; background: var(--cartao); }
360	.palco-jogo canvas { display: block; touch-action: none; }
361	.cartao-jogo-icone { width: 64px; height: 64px; object-fit: contain; }
