/* Segue DESIGN.md: cores calmas, contraste AA, alvos grandes, movimento curto. */
@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }

:root {
  /* Marca Gump: verde esmeralda + rosa rubi + pêssego sobre creme rosado. */
  --verde: #2E9E6B;
  --verde-forte: #1F7A50;
  --verde-claro: #EEF8F2;
  --rubi: #D9406E;
  --rubi-forte: #B8325A;
  --rubi-claro: #FBE1E9;
  --pessego: #FF9F6B;
  --pessego-claro: #FFE6D6;
  --papel: #FFF6F0;
  --cartao: #ffffff;
  --tinta: #1E3B2F;
  --suave: #55665D;
  --ok: var(--verde-forte);
  --alerta: #9A4A12;
  --erro: #A8324F;
  --borda: #EADBD0;
  --sombra: 0 1px 2px rgba(30, 59, 47, 0.06), 0 6px 20px rgba(30, 59, 47, 0.07);
  --titulo: 'Fredoka', 'Atkinson', sans-serif;
  /* Tokens do tema de hiperfoco (trocados por estiloTema()). */
  --tema: var(--verde);
  --tema-fundo: var(--verde-claro);
  --ceu: #DDEEE5;
  --chao: #BFDACA;
  --chao-longe: #D0E4D7;
  font-family: 'Atkinson', system-ui, sans-serif;
  color: var(--tinta);
  background: var(--papel);
  line-height: 1.5;
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--papel); }
h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 8px; }
h1 { font-size: 1.6rem; }
h2 { font-size: 1.2rem; }
a { color: var(--ok); }
img { max-width: 100%; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

button, .botao {
  font: inherit; font-weight: 700; color: var(--tinta);
  min-height: 48px; min-width: 48px; padding: 0 16px; gap: 8px;
  border: 2px solid var(--tinta); border-radius: 12px; background: var(--cartao);
  cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; justify-content: center;
  transition: transform 120ms ease, background-color 150ms ease, box-shadow 150ms ease;
}
button:active { transform: scale(0.97); }
button:disabled { opacity: 0.45; cursor: default; }
button.primario { background: var(--verde-forte); border-color: var(--verde-forte); color: #fff; }
button.primario:hover:not(:disabled) { background: var(--tinta); border-color: var(--tinta); }
button:focus-visible, .botao:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--ok); outline-offset: 3px; }

input, select { font: inherit; min-height: 48px; padding: 0 14px; border: 2px solid var(--borda); border-radius: 12px; background: var(--cartao); color: var(--tinta); }
input:hover, select:hover { border-color: #D9C4B5; }
input[type='file'] { padding: 10px; }
label { display: flex; flex-direction: column; gap: 6px; font-weight: 700; }

.ajuda { color: var(--suave); margin: 4px 0; }
.erro { color: var(--erro); font-weight: 700; }
.linha { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; }
.linha.centro { justify-content: center; }
.cartao { background: var(--cartao); border: 1px solid var(--borda); border-radius: 16px; padding: 20px; }

.link-voltar { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px 0 6px; border: none; border-radius: 10px; background: none; color: var(--verde-forte); font-weight: 700; text-decoration: none; }
.link-voltar:hover { background: var(--verde-claro); }

/* ---------------------------------------------------------------- Login */
.login { min-height: 100dvh; display: grid; grid-template-columns: 1fr 1fr; }
.login-marca { position: relative; overflow: hidden; background: var(--verde-claro); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 24px; padding: 48px 32px; text-align: center; }
.login-marca > :not(.bolha) { position: relative; }
.login-frase { margin: 0; max-width: 22ch; font-family: var(--titulo); font-weight: 600; font-size: 1.7rem; line-height: 1.25; color: var(--tinta); }
.bolha { position: absolute; border-radius: 50%; }
.bolha.b1 { width: 340px; height: 340px; background: var(--pessego-claro); top: -110px; left: -120px; }
.bolha.b2 { width: 220px; height: 220px; background: #F6C9D6; bottom: -60px; right: -50px; }
.bolha.b3 { width: 90px; height: 90px; background: var(--pessego); bottom: 22%; left: 12%; opacity: 0.55; }
.login-passos { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; text-align: left; }
.login-passos li { display: flex; align-items: center; gap: 12px; font-weight: 700; }
.login-passos li > span { flex: none; width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: var(--cartao); color: var(--verde-forte); box-shadow: var(--sombra); }
.login-turma { display: flex; gap: 6px; padding: 10px 16px; border-radius: 999px; background: rgba(255, 255, 255, 0.7); }
.login-turma img { width: 56px; height: 56px; }

.login-form { display: grid; place-items: center; padding: 32px 16px; background: var(--papel); }
.login-caixa { width: min(420px, 100%); display: flex; flex-direction: column; gap: 16px; }
.login-caixa h1 { font-family: var(--titulo); font-size: 2rem; margin: 0; }
.perfis { display: flex; flex-direction: column; gap: 12px; }
.perfil { justify-content: flex-start; gap: 16px; min-height: 84px; padding: 12px 18px 12px 12px; text-align: left; border: 2px solid var(--borda); border-radius: 18px; background: var(--cartao); box-shadow: var(--sombra); }
.perfil:hover { transform: translateY(-2px); }
.perfil > svg { margin-left: auto; color: var(--suave); }
.perfil-texto { display: flex; flex-direction: column; }
.perfil-texto strong { font-family: var(--titulo); font-size: 1.3rem; font-weight: 600; }
.perfil-texto span { font-weight: 400; color: var(--suave); }
.perfil-icone { flex: none; width: 56px; height: 56px; border-radius: 16px; display: grid; place-items: center; }
.perfil-verde .perfil-icone, .perfil-icone.perfil-verde { background: var(--verde-claro); color: var(--verde-forte); }
.perfil-rubi .perfil-icone, .perfil-icone.perfil-rubi { background: var(--rubi-claro); color: var(--rubi-forte); }
.perfil-pessego .perfil-icone, .perfil-icone.perfil-pessego { background: var(--pessego-claro); color: var(--alerta); }
.perfil-verde:hover { border-color: var(--verde); }
.perfil-rubi:hover { border-color: var(--rubi); }
.perfil-pessego:hover { border-color: var(--pessego); }
.login-titulo { display: flex; align-items: center; gap: 14px; }
.login-crianca input, .login-crianca button { min-height: 60px; font-size: 1.15rem; }
.demo { border-top: 1px solid var(--borda); padding-top: 14px; display: flex; flex-direction: column; gap: 10px; }
.demo p { margin: 0; color: var(--suave); }
.demo button { border: none; }
.demo-verde { background: var(--verde-claro); color: var(--verde-forte); }
.demo-rubi { background: var(--rubi-claro); color: var(--rubi-forte); }
.demo-pessego { background: var(--pessego-claro); color: var(--alerta); }

/* ---------------------------------------------------------------- Áreas de adulto */
.adulto { min-height: 100dvh; background: var(--papel); }
.cabecalho { position: sticky; top: 0; z-index: 5; display: flex; justify-content: space-between; align-items: center; gap: 12px 24px; flex-wrap: wrap; padding: 10px 24px; background: rgba(255, 255, 255, 0.92); backdrop-filter: blur(8px); border-bottom: 1px solid var(--borda); }
.cabecalho-marca { display: flex; align-items: center; gap: 14px; }
.cabecalho-titulo { padding: 4px 12px; border-radius: 999px; background: var(--verde-claro); color: var(--verde-forte); font-weight: 700; }
.cabecalho-meio { flex: 1; display: flex; justify-content: center; }
.cabecalho-acoes { display: flex; gap: 12px; align-items: center; }
.cabecalho-acoes button { border-color: var(--borda); }
.cabecalho-acoes button:hover { border-color: var(--tinta); }
.quem { display: inline-flex; align-items: center; gap: 8px; color: var(--suave); font-weight: 700; }
.quem-inicial { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--rubi-claro); color: var(--rubi-forte); font-family: var(--titulo); }
.seletor-aluno { flex-direction: row; align-items: center; gap: 10px; }
.seletor-aluno span { color: var(--suave); }
.conteudo { max-width: 1040px; margin: 0 auto; padding: 28px 16px 64px; display: flex; flex-direction: column; gap: 20px; }

.aluno-topo { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.aluno-topo > div { flex: 1; min-width: 180px; }
.aluno-topo h1 { font-family: var(--titulo); font-size: 2.2rem; margin: 0; }
.aluno-topo .ajuda { margin: 0; }
.aluno-avatar { flex: none; width: 76px; height: 76px; border-radius: 50%; overflow: hidden; display: grid; place-items: center; background: var(--pessego); color: var(--tinta); font-family: var(--titulo); font-weight: 700; font-size: 2rem; border: 3px solid var(--cartao); box-shadow: 0 0 0 3px var(--pessego); }
.aluno-avatar img { width: 82%; height: 82%; }
.fichas { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.fichas li { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; background: var(--cartao); border: 1px solid var(--borda); color: var(--suave); }
.fichas svg { color: var(--rubi-forte); }
.fichas strong { color: var(--tinta); font-size: 1.1rem; }

.passos { list-style: none; margin: 0; padding: 16px 20px; display: flex; gap: 8px; background: var(--cartao); border-radius: 18px; border: 1px solid var(--borda); }
.passos li { flex: 1; display: flex; align-items: center; gap: 10px; font-weight: 700; color: var(--suave); }
.passos li:not(:last-child)::after { content: ''; flex: 1; height: 3px; border-radius: 3px; background: var(--borda); margin-left: 4px; }
.passos li.feito:not(:last-child)::after { background: var(--verde); }
.passo-marca { flex: none; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: #F3E9E1; color: var(--suave); }
.passos li.atual { color: var(--tinta); }
.passos li.atual .passo-marca { background: var(--pessego); color: var(--tinta); }
.passos li.feito { color: var(--verde-forte); }
.passos li.feito .passo-marca { background: var(--verde-forte); color: #fff; }

.bloco { background: var(--cartao); border: 1px solid var(--borda); border-radius: 20px; padding: 24px; display: flex; flex-direction: column; gap: 14px; box-shadow: var(--sombra); }
.bloco h2 { font-family: var(--titulo); font-size: 1.45rem; font-weight: 600; margin: 0; }
.bloco > p { margin: 0; }
.bloco-titulo { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.nota-ia { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; font-size: 0.95rem; }
.vazio { margin: 0; padding: 20px; border-radius: 14px; background: var(--papel); color: var(--suave); text-align: center; }
.aviso-acao { margin: 0; padding: 12px 16px; border-radius: 12px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; display: flex; align-items: center; gap: 8px; }
.aviso-calmo { margin: 0; padding: 14px 16px; border-radius: 14px; background: var(--verde-claro); display: flex; gap: 12px; align-items: flex-start; }
.aviso-calmo svg { flex: none; color: var(--verde-forte); margin-top: 2px; }

.envio { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.soltar { width: 100%; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center; padding: 28px 16px; border: 2px dashed var(--verde); border-radius: 16px; background: var(--verde-claro); font-weight: 400; }
.soltar:hover, .soltar:focus-within { background: #E2F3E9; }
.soltar:focus-within { outline: 3px solid var(--verde-forte); outline-offset: 3px; }
.soltar strong { font-size: 1.1rem; }
.soltar input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.soltar-icone { width: 60px; height: 60px; border-radius: 50%; display: grid; place-items: center; background: var(--cartao); color: var(--verde-forte); }
.soltar.com-arquivo { border-style: solid; }

.grade-topicos { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
.topico { padding: 18px; border-radius: 16px; display: flex; flex-direction: column; gap: 8px; }
.topico p { margin: 0; color: var(--tinta); font-size: 0.95rem; }
.topico-icone { flex: none; width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center; background: var(--cartao); }
.cor-verde { background: var(--verde-claro); } .cor-verde .topico-icone, .sugestao-capa.cor-verde, .lista-jogos-icone.cor-verde { color: var(--verde-forte); }
.cor-rubi { background: var(--rubi-claro); } .cor-rubi .topico-icone, .sugestao-capa.cor-rubi, .lista-jogos-icone.cor-rubi { color: var(--rubi-forte); }
.cor-pessego { background: var(--pessego-claro); } .cor-pessego .topico-icone, .sugestao-capa.cor-pessego, .lista-jogos-icone.cor-pessego { color: var(--alerta); }

/* Resumo para a família: um cartão por tópico. */
.grade-topicos-pais { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; }
.topico-pais { padding: 20px; border-radius: 18px; display: flex; flex-direction: column; gap: 14px; }
.topico-pais-titulo { display: flex; align-items: center; gap: 12px; }
.topico-pais h3 { font-family: var(--titulo); font-weight: 600; font-size: 1.25rem; margin: 0; }
.topico-parte { background: rgba(255, 255, 255, 0.75); border-radius: 12px; padding: 12px 14px; }
.topico-parte h4 { display: flex; align-items: center; gap: 6px; font-size: 0.95rem; margin: 0 0 6px; color: var(--suave); }
.topico-parte p { margin: 0; }
.topico-parte ul { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 4px; }
.topico-parte .links { list-style: none; padding: 0; }
.links a { font-weight: 700; }

.grade-cartoes-jogo { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }
.cartao-sugestao { border: 2px solid var(--borda); border-radius: 18px; overflow: hidden; display: flex; flex-direction: column; background: var(--cartao); }
.sugestao-capa { position: relative; height: 110px; display: grid; place-items: center; }
.sugestao-capa .selo { position: absolute; top: 10px; right: 10px; background: var(--cartao); }
.sugestao-corpo { padding: 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.sugestao-corpo strong { font-size: 1.15rem; }
.sugestao-corpo .ajuda { margin: 0; }
.sugestao-corpo .linha { margin-top: auto; padding-top: 8px; }
.sugestao-corpo button { flex: 1; }
.cartao-sugestao.status-sugerido { border-color: var(--pessego); }
.cartao-sugestao.status-aprovado { border-color: var(--verde); }
.cartao-sugestao.status-recusado { opacity: 0.6; }

.lista-jogos { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; }
.lista-jogos li { display: flex; gap: 14px; align-items: center; padding: 14px; border: 1px solid var(--borda); border-radius: 16px; }
.lista-jogos .ajuda { margin: 0; }
.lista-jogos-icone { flex: none; width: 56px; height: 56px; border-radius: 16px; display: grid; place-items: center; }

.etiquetas { list-style: none; padding: 0; margin: 8px 0; display: flex; flex-wrap: wrap; gap: 8px; }
.etiquetas li { padding: 6px 12px; border-radius: 999px; background: var(--verde-claro); color: var(--ok); font-weight: 700; }
.etiquetas li:not(.do-pdi) { background: transparent; color: var(--tinta); border: 1px dashed currentColor; font-weight: 400; }
.etiquetas li.do-pdi { display: inline-flex; align-items: center; gap: 4px; }

.selo { font-size: 0.9rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; background: #F3E9E1; }
.status-sugerido .selo { background: var(--pessego-claro); color: var(--alerta); }
.status-aprovado .selo { background: var(--verde-claro); color: var(--ok); }

/* Desempenho: números de resumo + barras horizontais. */
.painel { display: flex; flex-direction: column; gap: 18px; }
.painel h3 { font-size: 1.05rem; margin: 0; }
.numeros { margin: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.numero { padding: 14px 16px; border-radius: 14px; background: var(--papel); border: 1px solid var(--borda); }
.numero dt { color: var(--suave); font-weight: 700; font-size: 0.95rem; }
.numero dd { margin: 2px 0 0; font-family: var(--titulo); font-weight: 600; font-size: 2rem; line-height: 1.1; }
.barras { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 14px; }
.barras-topo { display: flex; justify-content: space-between; gap: 12px; }
.barras-topo span { font-weight: 700; color: var(--verde-forte); }
.barras .ajuda { margin: 4px 0 0; font-size: 0.95rem; }
.barra { height: 14px; margin-top: 6px; border-radius: 999px; background: #F3E9E1; overflow: hidden; }
.barra span { display: block; height: 100%; border-radius: 999px; background: var(--verde); }

/* ---------------------------------------------------------------- Área da criança */
/* Mesma estrutura em todos os temas: só os tokens do tema mudam. */
.crianca { min-height: 100dvh; background: var(--tema-fundo); padding-bottom: 56px; font-size: 1.15rem; }
.crianca-barra { display: flex; justify-content: space-between; align-items: center; gap: 12px; max-width: 960px; margin: 0 auto; padding: 16px; }
.crianca button { min-height: 64px; border-radius: 18px; }
.botao-crianca { border: 2px solid color-mix(in srgb, var(--tema) 35%, transparent); background: var(--cartao); padding: 0 20px 0 14px; box-shadow: 0 3px 0 color-mix(in srgb, var(--tema) 25%, transparent); }
.botao-crianca:hover { border-color: var(--tema); }
.crianca button.primario { background: var(--tema); border-color: var(--tema); color: #fff; box-shadow: 0 4px 0 color-mix(in srgb, var(--tema) 60%, #000); }
.crianca button.primario:hover:not(:disabled) { background: color-mix(in srgb, var(--tema) 85%, #000); border-color: transparent; }
.crianca-erro { max-width: 960px; margin: 0 auto 12px; padding: 0 16px; }
.crianca-secao { max-width: 960px; margin: 0 auto; padding: 16px; }
.crianca-titulo { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-family: var(--titulo); font-weight: 600; font-size: 1.9rem; margin: 8px 0 16px; }
.titulo-icone { width: 48px; height: 48px; border-radius: 16px; display: grid; place-items: center; background: var(--tema); color: #fff; }
.contador { margin-left: auto; padding: 4px 14px; border-radius: 999px; background: var(--cartao); color: var(--tema); font-family: 'Atkinson', sans-serif; font-weight: 700; font-size: 1.05rem; }

/* Palco: cenário do tema com o personagem, o XP e o próximo item. */
.palco { position: relative; overflow: hidden; background: var(--ceu); }
.cenario { position: absolute; inset: 0; width: 100%; height: 100%; }
.c-ceu { fill: var(--ceu); }
.c-sol { fill: #fff; opacity: 0.55; }
.c-nuvem { fill: #fff; opacity: 0.75; }
.c-chao-longe { fill: var(--chao-longe); }
.c-chao { fill: var(--chao); }
.c-onda { fill: var(--tema-fundo); }
.c-detalhe { fill: color-mix(in srgb, var(--tema) 22%, var(--chao)); stroke: color-mix(in srgb, var(--tema) 22%, var(--chao)); }
.c-detalhe .c-lava { stroke: color-mix(in srgb, var(--pessego) 55%, var(--chao)); }
.c-detalhe-claro { stroke: #fff; opacity: 0.8; }
.palco-conteudo { position: relative; max-width: 960px; margin: 0 auto; padding: 24px 16px 64px; display: flex; align-items: flex-end; gap: 12px; }
.palco-personagem { flex: none; width: 190px; height: 190px; filter: drop-shadow(0 6px 0 rgba(30, 59, 47, 0.12)); }
.palco-balao { position: relative; flex: 1; max-width: 520px; margin-bottom: 28px; padding: 20px 24px; background: var(--cartao); border-radius: 24px; box-shadow: var(--sombra); }
.palco-balao::before { content: ''; position: absolute; left: -12px; bottom: 34px; width: 24px; height: 24px; background: var(--cartao); transform: rotate(45deg); border-radius: 4px; }
.palco-balao h1 { position: relative; font-family: var(--titulo); font-weight: 600; font-size: 2.3rem; margin: 0 0 10px; }
.xp-linha { display: flex; align-items: center; gap: 10px; }
.xp-estrela { flex: none; color: var(--pessego); }
.xp-estrela svg { fill: var(--pessego); stroke: var(--alerta); }
.xp { flex: 1; height: 26px; border-radius: 999px; background: var(--tema-fundo); border: 2px solid color-mix(in srgb, var(--tema) 25%, transparent); overflow: hidden; }
.xp span { display: block; height: 100%; border-radius: 999px; background: var(--tema); transition: width 300ms ease; }
.xp-proximo { flex: none; width: 52px; height: 52px; padding: 4px; border-radius: 14px; background: var(--tema-fundo); border: 2px dashed var(--tema); }
.xp-texto { margin: 8px 0 0; color: var(--suave); }
.xp-texto strong { color: var(--tinta); }

/* Escolha do tema */
.grade-temas { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 18px; margin-bottom: 20px; }
.crianca .cartao-tema { flex-direction: column; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--cartao); border-radius: 24px; background: var(--cartao); box-shadow: var(--sombra); }
.cartao-tema:hover { border-color: var(--tema); transform: translateY(-3px); }
.cartao-tema-arte { width: 100%; display: grid; place-items: center; padding: 18px; background: var(--ceu); }
.cartao-tema-arte img { width: 130px; height: 130px; }
.cartao-tema-nome { padding: 14px; font-family: var(--titulo); font-weight: 600; font-size: 1.4rem; color: var(--tema); }

/* Cartões de jogo: capa grande com arte do tema e botão de jogar. */
.grade-jogos { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 20px; }
.crianca .cartao-jogo { flex-direction: column; align-items: stretch; gap: 0; padding: 0; min-height: 0; overflow: hidden; border: 3px solid var(--cartao); border-radius: 26px; background: var(--cartao); box-shadow: var(--sombra); text-align: left; }
.cartao-jogo:hover { border-color: var(--tema); transform: translateY(-3px); }
.cartao-jogo:hover .cartao-jogo-play { background: color-mix(in srgb, var(--tema) 85%, #000); }
.cartao-jogo-capa { position: relative; display: grid; place-items: center; height: 170px; background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6) 0 60px, transparent 61px), var(--ceu); }
.capa-1 .cartao-jogo-capa { background: radial-gradient(circle at 75% 70%, rgba(255, 255, 255, 0.6) 0 70px, transparent 71px), var(--pessego-claro); }
.capa-2 .cartao-jogo-capa { background: radial-gradient(circle at 25% 75%, rgba(255, 255, 255, 0.6) 0 64px, transparent 65px), var(--rubi-claro); }
.cartao-jogo-capa img { width: 124px; height: 124px; }
.cartao-jogo-tipo { position: absolute; top: 12px; left: 12px; width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; background: var(--cartao); color: var(--tema); }
.cartao-jogo-rodape { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 14px 14px 18px; }
.cartao-jogo-nome { font-family: var(--titulo); font-weight: 600; font-size: 1.3rem; line-height: 1.2; }
.cartao-jogo-play { flex: none; width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center; background: var(--tema); color: #fff; transition: background-color 150ms ease; }
.cartao-jogo-play svg { fill: #fff; }
.crianca-vazio { display: flex; align-items: center; gap: 16px; margin: 0; padding: 20px; border-radius: 20px; background: var(--cartao); }

/* Coleção: estante com o item ganho, o próximo e os bloqueados (silhueta). */
.estante { list-style: none; margin: 0; padding: 20px; display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 14px; border-radius: 26px; background: var(--cartao); box-shadow: var(--sombra); }
.item-colecao { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 8px; border-radius: 18px; text-align: center; font-size: 0.95rem; font-weight: 700; line-height: 1.2; }
.item-colecao img { width: 72px; height: 72px; }
.item-colecao.ganho { background: var(--tema-fundo); }
.item-colecao.proximo { border: 2px dashed var(--tema); color: var(--tema); }
.item-colecao.proximo img { opacity: 0.4; filter: grayscale(1); }
.item-colecao.bloqueado { background: #F6F0EA; color: var(--suave); }
.item-colecao.bloqueado img { filter: brightness(0); opacity: 0.12; }

/* Tela do jogo */
.cartao-centro { display: flex; flex-direction: column; align-items: center; gap: 12px; text-align: center; max-width: 640px; margin-top: 24px; padding: 32px 24px; background: var(--cartao); border-radius: 28px; box-shadow: var(--sombra); }
.cartao-centro .crianca-titulo { justify-content: center; margin: 0; }
.personagem-centro { width: 150px; height: 150px; }
.passo-texto { display: flex; align-items: center; gap: 10px; margin: 0 0 8px; }
.passo-texto svg { flex: none; color: var(--tema); }
button.grande { min-height: 72px; padding: 0 32px; font-size: 1.25rem; }
.selo-estrela { width: 104px; height: 104px; border-radius: 50%; display: grid; place-items: center; background: var(--pessego-claro); color: var(--alerta); animation: aparecer 300ms ease-out; }
.selo-estrela svg { fill: var(--pessego); }
.item-novo { display: flex; align-items: center; gap: 16px; padding: 12px 20px 12px 12px; margin-bottom: 8px; border-radius: 20px; background: var(--tema-fundo); animation: aparecer 300ms ease-out; }
.item-novo img { width: 80px; height: 80px; }
.item-novo p { margin: 0; }
@keyframes aparecer { from { transform: scale(0.85); opacity: 0; } to { transform: scale(1); opacity: 1; } }

.fundo-dialogo { position: fixed; inset: 0; background: rgba(31, 42, 46, 0.45); display: grid; place-items: center; padding: 16px; }
.dialogo { background: var(--cartao); border-radius: 24px; padding: 28px 24px; max-width: 420px; width: 100%; text-align: center; box-shadow: var(--sombra); }
.dialogo p { font-family: var(--titulo); font-weight: 600; font-size: 1.5rem; margin: 8px 0 20px; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

@media (max-width: 760px) {
  .passos { flex-direction: column; align-items: stretch; }
  .passos li:not(:last-child)::after { display: none; }
  .cabecalho { padding: 10px 16px; }
  .cabecalho-meio { order: 3; flex-basis: 100%; justify-content: flex-start; }
  .quem { display: none; }
  .login { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
  .login-marca { padding: 32px 16px; gap: 12px; }
  .login-marca .logo { font-size: 48px !important; }
  .login-frase { font-size: 1.25rem; }
