}

@media (max-width: 600px) {
  .crianca-titulo { font-size: 1.5rem; }
  .estante { grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); padding: 14px; }
}

/* Logo do Gump */
.logo { display: inline-flex; align-items: center; gap: 0.1em; font-family: var(--titulo); font-weight: 700; color: #2E9E6B; letter-spacing: -0.02em; line-height: 1; }
.logo img { height: 1.45em; width: auto; }

/* Palco onde o jogo do hub é montado. Os jogos usam height:100%, então o palco precisa de altura definida. */
.crianca-jogo { display: flex; flex-direction: column; height: 100dvh; box-sizing: border-box; }
.crianca-jogo { padding-bottom: 0; }
.crianca-jogo .crianca-barra { width: 100%; box-sizing: border-box; }
.crianca-barra-titulo { font-family: var(--titulo); font-size: 1.4rem; }
