import { useEffect, useState } from 'react'
import { api } from '../api.js'
import { itensGanhos, temaPorId } from '../temas.js'
import AvatarAluno from './AvatarAluno.jsx'
import Cabecalho from './Cabecalho.jsx'
import { PainelDesempenho } from './Desempenho.jsx'
import Icone, { ICONE_HABILIDADE, ICONE_JOGO } from './Icones.jsx'

const CORES = ['verde', 'rubi', 'pessego']

// Um tópico do resumo: pontos para observar, atividades gerais e links curados.
// Tudo vem pronto de pdi/src/processarPdi.js; aqui só mostramos (nada de sugerir ações).
function Topico({ item, nome, cor }) {
  return (
    <li className={`topico-pais cor-${cor}`}>
      <div className="topico-pais-titulo">
        <span className="topico-icone"><Icone nome={ICONE_HABILIDADE[item.habilidade] ?? 'ia'} tamanho={28} /></span>
        <h3>{nome}</h3>
      </div>
      {item.atencao && (
        <div className="topico-parte">
          <h4><Icone nome="lupa" tamanho={18} /> Para observar</h4>
          <p>{item.atencao}</p>
        </div>
      )}
      {item.atividades?.length > 0 && (
        <div className="topico-parte">
          <h4><Icone nome="folha" tamanho={18} /> Atividades de estímulo</h4>
          <ul>{item.atividades.map((a) => <li key={a}>{a}</li>)}</ul>
        </div>
      )}
      {item.recursos?.length > 0 && (
        <div className="topico-parte">
          <h4><Icone nome="link" tamanho={18} /> Para pesquisar</h4>
          <ul className="links">
            {item.recursos.map((r) => (
              <li key={r.url}><a href={r.url} target="_blank" rel="noopener noreferrer">{r.nome}</a></li>
            ))}
          </ul>
        </div>
      )}
    </li>
  )
}

export default function Pais({ usuario, sair }) {
  const [dados, setDados] = useState(null)
  const [desempenho, setDesempenho] = useState(null)
  const [erro, setErro] = useState('')

  useEffect(() => {
    Promise.all([api(`/alunos/${usuario.aluno_id}`), api(`/alunos/${usuario.aluno_id}/desempenho`)])
      .then(([d, des]) => {
        setDados(d)
        setDesempenho(des)
      })
      .catch((e) => setErro(e.message))
  }, [usuario.aluno_id])

  const nome = dados?.aluno.nome ?? 'a criança'
  const resumo = dados?.resumo
  const tema = temaPorId(dados?.aluno.hiperfoco)
  const porHabilidade = resumo?.porHabilidade ?? []

  return (
    <div className="adulto">
      <Cabecalho usuario={usuario} sair={sair} titulo="Família" />
      <main className="conteudo">
        {erro && <p className="erro" role="alert">{erro}</p>}

        {dados && (
          <section className="aluno-topo">
            <AvatarAluno aluno={dados.aluno} tema={tema} />
            <div>
              <h1>Plano de {nome}</h1>
              <p className="ajuda">{tema ? `Tema favorito: ${tema.nome}` : `${nome} ainda não escolheu o tema favorito`}</p>
            </div>
            <ul className="fichas">
              <li><Icone nome="estrela" tamanho={20} /><strong>{dados.xp}</strong> XP</li>
              <li><Icone nome="trofeu" tamanho={20} /><strong>{itensGanhos(tema, dados.xp)}</strong> itens</li>
              <li><Icone nome="jogar" tamanho={20} /><strong>{dados.jogos.length}</strong> jogos</li>
            </ul>
          </section>
        )}

        <section className="bloco">
          <div className="bloco-titulo">
            <h2>O que a escola identificou</h2>
            <span className="nota-ia"><Icone nome="info" tamanho={18} /> Não é diagnóstico</span>
          </div>
          {resumo?.topicos?.length ? (
            <>
              <p>A escola identificou no PDI estes tópicos para trabalhar com {nome}. Pesquise sobre eles e converse com a escola e com os profissionais que acompanham {nome}.</p>
              {porHabilidade.length ? (
                <ul className="grade-topicos-pais">
                  {porHabilidade.map((item, i) => (
                    <Topico key={item.habilidade} item={item} nome={resumo.topicos[i] ?? item.habilidade} cor={CORES[i % CORES.length]} />
                  ))}
                </ul>
              ) : (
                <ul className="etiquetas">{resumo.topicos.map((t) => <li key={t}>{t}</li>)}</ul>
              )}
              {resumo.tempoRevisao && (
                <p className="aviso-calmo"><Icone nome="calendario" /> {resumo.tempoRevisao}</p>
              )}
              {resumo.aviso && <p className="ajuda">{resumo.aviso}</p>}
            </>
          ) : (
            <p className="vazio">A escola ainda não enviou o PDI.</p>
          )}
        </section>

        <section className="bloco">
          <h2>Jogos aprovados pela escola</h2>
          {dados?.jogos.length ? (
            <ul className="lista-jogos">
              {dados.jogos.map((j, i) => (
                <li key={j.id}>
                  <span className={`lista-jogos-icone cor-${CORES[i % CORES.length]}`}><Icone nome={ICONE_JOGO[j.id] ?? 'memoria'} tamanho={28} /></span>
                  <div>
                    <strong>{j.nome}</strong>
                    <p className="ajuda">{j.descricao}</p>
                  </div>
                </li>
              ))}
            </ul>
          ) : (
            <p className="vazio">Nenhum jogo aprovado ainda.</p>
          )}
          <p className="ajuda">Incentive {nome} a jogar um pouco por dia, sem pressa.</p>
        </section>

        <section className="bloco">
          <h2>Como {nome} está indo</h2>
          {desempenho && <PainelDesempenho desempenho={desempenho} />}
        </section>
      </main>
    </div>
  )
}
rotas.param('alunoId', (req, res, next, alunoId) => {
  if (!podeVerAluno(req.usuario, alunoId)) return res.status(403).json({ erro: 'Sem acesso a este aluno.' })
  next()
})

rotas.get('/alunos', soEscola, async (req, res) => {
  res.json(await q(db.from('alunos').select('id, nome').order('nome')))
})

rotas.get('/habilidades', (req, res) => res.json(HABILIDADES))

async function ultimoPdi(alunoId) {
  const [pdi] = await q(db.from('pdis').select('*').eq('aluno_id', alunoId).order('criado_em', { ascending: false }).limit(1))
  return pdi ?? null
}

// Visão do aluno adaptada ao perfil de quem pede.
rotas.get('/alunos/:alunoId', async (req, res) => {
  const { alunoId } = req.params
  const [aluno] = await q(db.from('alunos').select('*').eq('id', alunoId).limit(1))
  if (!aluno) return res.status(404).json({ erro: 'Aluno não encontrado.' })

  const [pdi, jogos, aprovacoes, resultados] = await Promise.all([
    ultimoPdi(alunoId),
    q(db.from('jogos').select('*').order('nome')),
    q(db.from('aprovacoes').select('jogo_id, status').eq('aluno_id', alunoId)),
    q(db.from('resultados').select('status').eq('aluno_id', alunoId)),
  ])

  const statusPorJogo = Object.fromEntries(aprovacoes.map((a) => [a.jogo_id, a.status]))
  const itensPdi = pdi?.itens ?? []
  const comStatus = jogos
    .filter((j) => statusPorJogo[j.id])
    .map((j) => ({ ...j, status: statusPorJogo[j.id], nivel: nivelDoJogo(itensPdi, j) }))
  const xp = calcularXp(resultados)
  const { perfil } = req.usuario

  if (perfil === 'crianca') {
    // A criança vê só os jogos aprovados para ela, nunca o banco inteiro.
    return res.json({ aluno, xp, jogos: comStatus.filter((j) => j.status === 'aprovado') })
  }

  if (perfil === 'responsavel') {
    // Resumo completo para os pais: tópicos, pontos de atenção e atividades
    // por habilidade, links de pesquisa curados e aviso — tudo já vem pronto
    // e validado de processarPdi() (ver pdi/src/processarPdi.js), nunca
    // gerado aqui. Nenhuma ação é sugerida.
    const resumo = pdi?.resumo_pais ?? null
    return res.json({ aluno, xp, resumo, jogos: comStatus.filter((j) => j.status === 'aprovado') })
  }

  res.json({ aluno, xp, pdi, jogos: comStatus })
})

// Envio do PDI em PDF: extrai o texto, a IA identifica as habilidades e o site sugere jogos.
rotas.post('/alunos/:alunoId/pdi', soEscola, upload.single('pdf'), async (req, res) => {
  if (!req.file) return res.status(400).json({ erro: 'Envie um arquivo PDF no campo "pdf".' })
  const { alunoId } = req.params

  // Import tardio: o servidor sobe mesmo sem as dependências de pdi/ instaladas.
  const [{ extrairTexto }, { processarPdi }, { chamarFeatherless }] = await Promise.all([
    import('../../../pdi/src/extrairTexto.js'),
    import('../../../pdi/src/processarPdi.js'),
    import('../../../pdi/src/featherlessClient.js'),
  ])

  const texto = await extrairTexto(req.file.buffer)
  const resultado = await processarPdi(texto, HABILIDADES, chamarFeatherless)

  const [pdi] = await q(
    db.from('pdis').insert({
      aluno_id: alunoId,
      arquivo: req.file.originalname,
      itens: resultado.itens,
      resumo_pais: resultado.resumoPais,
      erro: resultado.erro ?? null,
    }).select(),
  )

  // Um PDI novo recomeça a aprovação: os jogos sugeridos voltam a "sugerido".
  await q(db.from('aprovacoes').delete().eq('aluno_id', alunoId))
  const sugeridos = sugerirJogos(resultado.itens, await q(db.from('jogos').select('*')))
  if (sugeridos.length) {
    await q(db.from('aprovacoes').insert(sugeridos.map((j) => ({ aluno_id: alunoId, jogo_id: j.id, status: 'sugerido' }))))
  }

  res.status(resultado.erro === 'pdf-sem-texto' ? 422 : 201).json({ pdi, sugeridos: sugeridos.map((j) => j.id) })
})

rotas.patch('/alunos/:alunoId/jogos/:jogoId', soEscola, async (req, res) => {
  const { status } = req.body ?? {}
  if (!['aprovado', 'recusado', 'sugerido'].includes(status)) return res.status(400).json({ erro: 'Status inválido.' })
  const linhas = await q(
    db.from('aprovacoes').update({ status, atualizado_em: new Date().toISOString() })
      .eq('aluno_id', req.params.alunoId).eq('jogo_id', req.params.jogoId).select(),
  )
  if (!linhas.length) return res.status(404).json({ erro: 'Este jogo não foi sugerido para o aluno.' })
  res.json(linhas[0])
})

rotas.patch('/alunos/:alunoId/hiperfoco', async (req, res) => {
  const { hiperfoco } = req.body ?? {}
  if (typeof hiperfoco !== 'string' || !hiperfoco) return res.status(400).json({ erro: 'Hiperfoco inválido.' })
  const [aluno] = await q(db.from('alunos').update({ hiperfoco }).eq('id', req.params.alunoId).select())
  res.json(aluno)
})

// Recebe o resultado de uma partida, no formato de createResult() dos jogos.
rotas.post('/alunos/:alunoId/resultados', async (req, res) => {
  const { jogoId, status, attempts, correct, hints = 0 } = req.body ?? {}
  const erro = validarResultado({ status, attempts, correct, hints })
  if (erro) return res.status(400).json({ erro })

  const [aprovacao] = await q(
    db.from('aprovacoes').select('status').eq('aluno_id', req.params.alunoId).eq('jogo_id', jogoId).limit(1),
  )
  if (aprovacao?.status !== 'aprovado') return res.status(403).json({ erro: 'Jogo não aprovado para este aluno.' })

  await q(db.from('resultados').insert({ aluno_id: req.params.alunoId, jogo_id: jogoId, status, attempts, correct, hints }))
  const resultados = await q(db.from('resultados').select('status').eq('aluno_id', req.params.alunoId))
  res.status(201).json({ xp: calcularXp(resultados) })
})

rotas.get('/alunos/:alunoId/desempenho', async (req, res) => {
  if (req.usuario.perfil === 'crianca') return res.status(403).json({ erro: 'Sem acesso.' })
  const [jogos, resultados] = await Promise.all([
    q(db.from('jogos').select('id, nome').order('nome')),
    q(db.from('resultados').select('*').eq('aluno_id', req.params.alunoId)),
  ])
  res.json({ porJogo: resumirDesempenho(resultados, jogos), totalPartidas: resultados.length, xp: calcularXp(resultados) })
})
// Regras puras do site, sem banco, para poder testar.

export const XP_POR_JOGO = 10
export const XP_POR_ITEM = 20

// Jogos do catálogo que treinam pelo menos uma habilidade (tag) do PDI.
// Os que cobrem mais tópicos do PDI vêm primeiro.
export function sugerirJogos(itens, jogos) {
  const habilidades = new Set(itens.map((i) => i.habilidade))
  const cobertas = (j) => j.habilidades.filter((h) => habilidades.has(h)).length
  return jogos.filter((j) => cobertas(j) > 0).sort((a, b) => cobertas(b) - cobertas(a))
}

// Nível (1 a 3) que o jogo recebe: o maior nível, entre as tags do PDI que o jogo treina.
export function nivelDoJogo(itens, jogo) {
  const niveis = itens.filter((i) => jogo.habilidades.includes(i.habilidade)).map((i) => Number(i.nivel))
  const nivel = Math.max(1, ...niveis.filter(Number.isFinite))
  return Math.min(3, Math.round(nivel))
}

export function calcularXp(resultados) {
  return resultados.filter((r) => r.status === 'completed').length * XP_POR_JOGO
}

export function itensDesbloqueados(xp) {
  return Math.floor(xp / XP_POR_ITEM)
}

// Resumo simplificado por jogo: partidas, conclusão e taxa de acerto.
export function resumirDesempenho(resultados, jogos) {
  return jogos.map((jogo) => {
    const doJogo = resultados.filter((r) => r.jogo_id === jogo.id)
    const tentativas = doJogo.reduce((s, r) => s + r.attempts, 0)
    const acertos = doJogo.reduce((s, r) => s + r.correct, 0)
    return {
      jogoId: jogo.id,
      nome: jogo.nome,
      partidas: doJogo.length,
      concluidas: doJogo.filter((r) => r.status === 'completed').length,
      dicas: doJogo.reduce((s, r) => s + r.hints, 0),
      taxaAcerto: tentativas ? Math.round((acertos / tentativas) * 100) : null,
    }
  })
}

export function validarResultado({ status, attempts, correct, hints = 0 }) {
  if (!['completed', 'abandoned'].includes(status)) return 'status inválido'
  const ok = [attempts, correct, hints].every((n) => Number.isSafeInteger(n) && n >= 0)
  if (!ok || correct > attempts) return 'contadores inválidos'
  return null
}

