import { chromium } from 'playwright-core'
const b = await chromium.launch({ executablePath: process.env.HOME + '/.cache/ms-playwright/chromium-1148/chrome-linux/chrome' })
const base = 'http://127.0.0.1:5180'
async function shot(nome, url, usuario, w = 1440, h = 900, full = false) {
  const ctx = await b.newContext({ viewport: { width: w, height: h } })
  const p = await ctx.newPage()
  const erros = []
  p.on('pageerror', (e) => erros.push(e.message))
  p.on('console', (m) => m.type() === 'error' && erros.push(m.text()))
  if (usuario) { await p.goto(base + '/entrar'); await p.evaluate((u) => localStorage.setItem('dopamine-usuario', JSON.stringify(u)), usuario) }
  await p.goto(base + url); await p.waitForTimeout(1800)
  await p.screenshot({ path: nome + '.png', fullPage: full })
  if (erros.length) console.log(nome, erros)
